// Sample data for exercise 28. Do not edit this file.
//
// The tree is deep-frozen on purpose. If your code ever changes a comment in
// place (comment.votes++, comment.replies.push(...)), JavaScript throws a
// TypeError right away and you find the bug immediately. Always build new
// objects and arrays instead.

function deepFreeze(value) {
  Object.values(value).forEach((child) => {
    if (typeof child === 'object' && child !== null) deepFreeze(child)
  })
  return Object.freeze(value)
}

